public class GridTools {
    /** Returns a new two-dimensional array that is the transpose of grid: for every row r and column c,
     *  element [c][r] of the result equals element [r][c] of grid. The array grid is not modified.
     *  Precondition: grid is rectangular and has at least one row and one column. */
    public static int[][] transpose(int[][] grid) { /* to be written */ }
}
```

