    public static int[][] transpose(int[][] grid) {
        int[][] result = new int[grid[0].length][grid.length];
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                result[c][r] = grid[r][c];
            }
        }
        return result;
    }
```

